        actions.add(getActionForkPseudoState());
        actions.add(getActionJoinPseudoState());
        actions.add(getActionShallowHistoryPseudoState());
        actions.add(getActionDeepHistoryPseudoState());
        actions.add(null);
        actions.add(getTriggerActions());
