def api(f):
    f.is_cache_api = True
    return f


def read_api(f):
    f = api(f)
    f.is_read_api = True
    return f


def write_api(f):
    f = api(f)
    f.is_read_api = False
    return f


def wrap_simple(lock, func):
    @wraps(func)
    def call_func_with_lock(*args, **kwargs):
        try:
            with lock:
                return func(*args, **kwargs)
        except DowngradeLockError:
            # We already have an exclusive lock, no need to acquire a shared
            # lock. See the safe_read_lock properties' documentation for why
            # this is necessary.
            return func(*args, **kwargs)
    return call_func_with_lock


def run_import_plugins(path_or_stream, fmt):
    """
    Run import plugins on the given file or stream.

    If *path_or_stream* is a file-like object, it is copied to a temporary
    file and the path to that file is returned. If it is a path string,
    the path is returned unchanged. The temporary file is closed after
    copying, but remains on disk for the plugins to use.
    """
    fmt = fmt.lower()
    if isinstance(path_or_stream, basestring):
        path = path_or_stream
    else:
        path_or_stream.seek(0)
        with PersistentTemporaryFile('_import_plugin.' + fmt) as pt:
            shutil.copyfileobj(path_or_stream, pt, length=1024 * 1024)
            path = pt.name
    return run_plugins_on_import(path, fmt)


