def api(f):
    f.is_cache_api = True
    return f


def read_api(f):
    f = api(f)
    f.is_read_api = True
    return f


def write_api(f):
    f = api(f)
    f.is_read_api = False
    return f


def wrap_simple(lock, func):
    @wraps(func)
    def call_func_with_lock(*args, **kwargs):
        try:
            with lock:
                return func(*args, **kwargs)
        except DowngradeLockError:
            # We already have an exclusive lock, no need to acquire a shared
            # lock. See the safe_read_lock properties' documentation for why
            # this is necessary.
            return func(*args, **kwargs)
    return call_func_with_lock


def run_import_plugins(path_or_stream, fmt):
    """
    Prepare a path for import plugins. If *path_or_stream* is a file-like
    object, copy its contents to a temporary file and return the temporary
    file's name. If it is a path string, return it unchanged.
    """
    fmt = fmt.lower()
    if isinstance(path_or_stream, basestring):
        # Already a path; no need to copy
        path = path_or_stream
    else:
        # File-like object: copy to a temporary file
        path_or_stream.seek(0)
        pt = PersistentTemporaryFile('_import_plugin.' + fmt)
        shutil.copyfileobj(path_or_stream, pt, 1024**2)
        pt.close()
        path = pt.name
    return run_plugins_on_import(path, fmt)


