    return f


def wrap_simple(lock, func):
    @wraps(func)
    def call_func_with_lock(*args, **kwargs):
        try:
            with lock:
                return func(*args, **kwargs)
        except DowngradeLockError:
            return func(*args, **kwargs)
    return call_func_with_lock


def _copy_to_temp(fileobj, fmt):
    """Copy a file-like object to a temporary file and return its name."""
    fileobj.seek(0)
    pt = PersistentTemporaryFile('_import_plugin.' + fmt)
    shutil.copyfileobj(fileobj, pt)
    pt.close()
    return pt.name


def run_import_plugins(path_or_stream, fmt):
    fmt = fmt.lower()
    if isinstance(path_or_stream, basestring):
        path = path_or_stream
    else:
        path = _copy_to_temp(path_or_stream, fmt)
    return run_plugins_on_import(path, fmt)


